{
  "headline": "FDA's records trace our supply to a plant with multiple OAI inspections and Warning Letters before and after the shortage posting",
  "headline_cites": ["E34", "E4", "E5", "E10", "E12", "E13", "E20", "E21", "E23", "E25", "E27", "E31", "E32", "E33", "D3", "D4", "D5", "D6", "D7", "D10", "D11"],
  "sentences": [
    {
      "text": "Our sterile water supply comes from Nephron SC, LLC (FEI 3010892830) as shown on the product label.",
      "cites": ["E34"]
    },
    {
      "text": "FDA inspected this plant in 2011 and classified it OAI, with the classification known by 2011-09-15.",
      "cites": ["E4", "E5"]
    },
    {
      "text": "A 2014 inspection was also classified OAI with 18 Form 483 observations, known by 2014-05-22.",
      "cites": ["E10", "E12"]
    },
    {
      "text": "Another OAI inspection occurred in 2015, known by 2015-11-12.",
      "cites": ["E13"]
    },
    {
      "text": "FDA issued a Warning Letter on 2013-09-24 and another on 2016-09-02 for this facility.",
      "cites": ["E29", "E30"]
    },
    {
      "text": "The shortage was first posted by FDA on 2021-11-23.",
      "cites": ["E48"]
    },
    {
      "text": "A 2019 inspection ended 2019-11-15 and was classified VAI, with the classification letter dated 2022-04-13 — 739 days before the shortage posting.",
      "cites": ["D3"]
    },
    {
      "text": "A Warning Letter was issued 2020-09-22 — 427 days before the shortage posting.",
      "cites": ["D4"]
    },
    {
      "text": "An inspection ending 2022-04-20 was classified OAI with 6 observations citing validation lacking for sterile drug products — 148 days after the shortage posting.",
      "cites": ["D5"]
    },
    {
      "text": "Warning Letters followed on 2022-10-11 and 2022-10-21 — 322 and 332 days after the shortage posting.",
      "cites": ["D6", "D7"]
    },
    {
      "text": "Class II recalls for sterile water from this firm started 2023-01-12 and 2023-02-23 — 415 and 457 days after the shortage posting.",
      "cites": ["D8", "D11"]
    },
    {
      "text": "A 2023-02-10 inspection was classified OAI with 15 observations citing SOPs not followed and validation lacking — 444 days after the shortage posting.",
      "cites": ["D10"]
    },
    {
      "text": "Subsequent inspections in 2024-02-09 and 2024-09-25 were also classified OAI.",
      "cites": ["E25", "E27"]
    },
    {
      "text": "The most recent inspection ended 2025-08-22 and was classified VAI.",
      "cites": ["E28"]
    },
    {
      "text": "As of 2026-10-21 the shortage has been on FDA's list for 59 months.",
      "cites": ["D15"]
    },
    {
      "text": "Corvale East has 3 days on hand and Corvale General has 8 days on hand at current usage.",
      "cites": ["D1", "D2"]
    },
    {
      "text": "The approved therapeutic interchange is WATER 1 mL/mL from Hospira, Inc. (NDC 00409488710), same product alternate manufacturer, approved by Riley Brooks, PharmD on 2026-05-18.",
      "cites": ["E49", "D12"]
    }
  ]
}
